#include <stdio.h>
#include <stdlib.h>

// Fenwick tree (Binary Indexed Tree) for counting inversions
typedef struct {
    int n;
    int* tree;
} BIT;

BIT* BIT_new(int n) {
    BIT* bit = (BIT*)malloc(sizeof(BIT));
    bit->n = n;
    bit->tree = (int*)calloc(n + 1, sizeof(int));
    return bit;
}

void BIT_add(BIT* bit, int idx, int delta) {
    while (idx <= bit->n) {
        bit->tree[idx] += delta;
        idx += idx & -idx;
    }
}

int BIT_sum(BIT* bit, int idx) {
    int s = 0;
    while (idx > 0) {
        s += bit->tree[idx];
        idx -= idx & -idx;
    }
    return s;
}

void BIT_free(BIT* bit) {
    free(bit->tree);
    free(bit);
}

int main() {
    int N;
    scanf("%d", &N);

    int* a = (int*)malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) {
        scanf("%d", &a[i]);
    }

    // Count inversions using BIT
    BIT* bit = BIT_new(N);
    long long inv_count = 0;
    for (int i = 0; i < N; i++) {
        inv_count += BIT_sum(bit, N) - BIT_sum(bit, a[i]);
        BIT_add(bit, a[i], 1);
    }

    // The required value is the number of inversions in the permutation
    printf("%lld\n", inv_count);

    BIT_free(bit);
    free(a);
    return 0;
}

