int main() {
    int n;
    scanf("%d", &n);

    long long *a = malloc(n * sizeof(long long));
    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }

    // For each element, find the span where it's the minimum
    // Using monotonic stack
    int *left = malloc(n * sizeof(int));
    int *right = malloc(n * sizeof(int));
    int *stack = malloc(n * sizeof(int));
    int top = 0;

    // Find left boundary (nearest smaller to left)
    for (int i = 0; i < n; i++) {
        while (top > 0 && a[stack[top-1]] >= a[i]) top--;
        left[i] = (top == 0) ? -1 : stack[top-1];
        stack[top++] = i;
    }

    top = 0;
    // Find right boundary (nearest smaller to right)
    for (int i = n-1; i >= 0; i--) {
        while (top > 0 && a[stack[top-1]] >= a[i]) top--;
        right[i] = (top == 0) ? n : stack[top-1];
        stack[top++] = i;
    }

    long long ans = 0;
    for (int i = 0; i < n; i++) {
        long long len = (long long)(right[i] - left[i] - 1);
        long long val = a[i] * len;
        if (val > ans) ans = val;
    }

    printf("%lld\n", ans);

    free(a); free(left); free(right); free(stack);
    return 0;
}

