typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *pos = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) {
        int x;
        scanf("%d", &x);
        pos[x] = i;
    }

    ll *ans = (ll *)malloc((N + 1) * sizeof(ll));
    ll *arr = (ll *)malloc((N + 2) * sizeof(ll));

    int m = 0;
    arr[m++] = 0;
    arr[m++] = N + 1;

    for (int x = N; x >= 1; x--) {
        int p = pos[x];

        qsort(arr, m, sizeof(ll), cmp_ll);

        int l = 0, r = m;
        while (r - l > 1) {
            int mid = (l + r) / 2;
            if (arr[mid] < p) l = mid;
            else r = mid;
        }

        ll L = arr[l];
        ll R = arr[r];
        ans[x] = (ll)(p - L) * (R - p);

        arr[m++] = p;
    }

    for (int i = 1; i <= N; i++) {
        printf("%lld\n", ans[i]);
    }

    free(pos);
    free(ans);
    free(arr);
    return 0;
}

