int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> a(N + 1), pos(N + 1);
    for (int i = 1; i <= N; ++i) {
        cin >> a[i];
        pos[a[i]] = i;
    }

    set<int> s;
    s.insert(0);
    s.insert(0);
    s.insert(N + 1);
    s.insert(N + 1);

    long long ans = 0;

    for (int x = N; x >= 1; --x) {
        int p = pos[x];
        auto it = s.lower_bound(p);

        int r1 = *it; ++it;
        int r2 = *it;
        --it; --it;
        int l1 = *it; --it;
        int l2 = *it;

        long long cnt = 1LL * (l1 - l2) * (r1 - p) + 1LL * (p - l1) * (r2 - r1);
        ans += 1LL * x * cnt;

        s.insert(p);
    }

    cout << ans << '\n';
    return 0;
}

