public class Main {
    static long mergeCount(int[] arr, int l, int r) {
        if (r - l <= 1) return 0;
        int mid = (l + r) / 2;
        long count = mergeCount(arr, l, mid) + mergeCount(arr, mid, r);
        int[] tmp = new int[r - l];
        int i = l, j = mid, k = 0;
        while (i < mid && j < r) {
            if (arr[i] <= arr[j]) {
                tmp[k++] = arr[i++];
            } else {
                count += mid - i;
                tmp[k++] = arr[j++];
            }
        }
        while (i < mid) tmp[k++] = arr[i++];
        while (j < r) tmp[k++] = arr[j++];
        for (int x = 0; x < tmp.length; x++) arr[l + x] = tmp[x];
        return count;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());
        System.out.println(mergeCount(a, 0, n));
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int[] pos = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            int a = fs.nextInt();
            pos[a] = i;
        }

        // TreeSet keeps positions of already processed larger values.
        // Add sentinels twice on each side to simplify counting.
        TreeSet<Integer> set = new TreeSet<>();
        set.add(0);
        set.add(0);
        set.add(N + 1);
        set.add(N + 1);

        long ans = 0;

        for (int x = N; x >= 1; x--) {
            int p = pos[x];

            Integer r1 = set.higher(p);
            Integer r2 = set.higher(r1);
            Integer l1 = set.lower(p);
            Integer l2 = set.lower(l1);

            long leftCount = l1 - l2;
            long midLeft = p - l1;
            long rightCount = r2 - r1;
            long midRight = r1 - p;

            // Number of subarrays where x is the second maximum:
            // choose one larger element on the left nearest side, or on the right nearest side.
            long cnt = leftCount * midRight + midLeft * rightCount;
            ans += cnt * x;

            set.add(p);
        }

        System.out.println(ans);
    }
}
